-- =====================================================================
-- Base de dados complementar: ecommerce_nexashop
-- Cenario: NexaShop (e-commerce ficticio) - atividade de consolidacao
-- Unidades 1 a 3 (SELECT, filtros, agregacoes, CASE) - sem necessidade de JOIN
-- Gerado para fins didaticos - UNISENAI / ADS
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS ecommerce_nexashop;
CREATE DATABASE ecommerce_nexashop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ecommerce_nexashop;

-- ---------------------------------------------------------------------
-- Tabela: clientes
-- ---------------------------------------------------------------------
CREATE TABLE clientes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(120) NOT NULL,
    email VARCHAR(160) NOT NULL,
    telefone VARCHAR(20) NULL,
    cidade VARCHAR(80) NOT NULL,
    estado CHAR(2) NOT NULL,
    data_nascimento DATE NOT NULL,
    data_cadastro DATE NOT NULL,
    segmento VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL,
    INDEX idx_clientes_estado (estado),
    INDEX idx_clientes_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- Tabela: produtos
-- ---------------------------------------------------------------------
CREATE TABLE produtos (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(150) NOT NULL,
    categoria VARCHAR(60) NOT NULL,
    marca VARCHAR(60) NOT NULL,
    preco DECIMAL(10,2) NOT NULL,
    estoque INT NOT NULL,
    ativo TINYINT(1) NOT NULL DEFAULT 1,
    INDEX idx_produtos_categoria (categoria)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- Tabela: pedidos
-- (cliente_id e produto_id ja preparados para a futura unidade de JOIN)
-- ---------------------------------------------------------------------
CREATE TABLE pedidos (
    id INT AUTO_INCREMENT PRIMARY KEY,
    cliente_id INT NOT NULL,
    produto_id INT NOT NULL,
    data_pedido DATE NOT NULL,
    quantidade INT NOT NULL,
    valor_total DECIMAL(10,2) NOT NULL,
    forma_pagamento VARCHAR(30) NOT NULL,
    canal_venda VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL,
    cupom_desconto VARCHAR(20) NULL,
    INDEX idx_pedidos_cliente_id (cliente_id),
    INDEX idx_pedidos_produto_id (produto_id),
    INDEX idx_pedidos_status (status),
    CONSTRAINT fk_pedidos_cliente FOREIGN KEY (cliente_id) REFERENCES clientes(id),
    CONSTRAINT fk_pedidos_produto FOREIGN KEY (produto_id) REFERENCES produtos(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- Tabela: avaliacoes
-- ---------------------------------------------------------------------
CREATE TABLE avaliacoes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    pedido_id INT NOT NULL,
    nota INT NOT NULL,
    comentario VARCHAR(255) NULL,
    data_avaliacao DATE NOT NULL,
    respondida_pela_loja TINYINT(1) NOT NULL DEFAULT 0,
    INDEX idx_avaliacoes_pedido_id (pedido_id),
    CONSTRAINT fk_avaliacoes_pedido FOREIGN KEY (pedido_id) REFERENCES pedidos(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

